"""Attention-guided prioritization for Sivand reduction.

Low-attention tokens are more likely removable without changing the
model's prediction, so the attention-guided traversal processes nodes
with LOW mean attention first (opposite of the token-count ordering
used by vanilla Perses, which tries the largest subtrees first).
"""

from __future__ import annotations
import heapq
import itertools
from typing import Dict, Iterable, List, Tuple

from reduction.token import Token
from reduction.tree import SparTreeNode
from reduction.sivand.model_oracle import MockModel


class AttentionExtractor:
    """Extracts token-level attention weights from a MockModel."""

    def __init__(self, model: MockModel):
        """Initialize the extractor with the model to query."""
        self.model = model

    def extract(self, source: str) -> List[Tuple[Token, float]]:
        """Return (token, attention) pairs for a source string."""
        tokens = self.model.tokenizer.tokenize(source)
        return self.extract_for_tokens(tokens)

    def extract_for_tokens(
            self, tokens: List[Token]) -> List[Tuple[Token, float]]:
        """Return (token, attention) pairs for an existing token list."""
        prediction = self.model.predict_tokens(list(tokens))
        return list(zip(tokens, prediction.attention_weights))

    def attention_map(self, tokens: List[Token]) -> Dict[Tuple[int, int], float]:
        """Map (line, col) of each token to its attention weight."""
        return {(t.line, t.col): w for t, w in self.extract_for_tokens(tokens)}

    def node_attention(self, node: SparTreeNode) -> float:
        """Mean attention weight over a node's (non-deleted) tokens."""
        tokens = node.tokens()
        if not tokens:
            return 0.0
        attention = self.model.predict_tokens(tokens).attention_weights
        return sum(attention) / len(attention)

    def build_queue(
            self, nodes: Iterable[SparTreeNode]) -> "AttentionPriorityQueue":
        """Build a low-attention-first priority queue over the given nodes."""
        queue = AttentionPriorityQueue()
        for node in nodes:
            queue.push(node, self.node_attention(node))
        return queue


class AttentionPriorityQueue:
    """Min-priority queue over SparTree nodes ordered by attention weight.

    Nodes with the LOWEST attention are popped first, under the
    heuristic that tokens the model barely attends to are the most
    likely to be removable while preserving its prediction. Ties are
    broken by insertion order (FIFO) for determinism.
    """

    def __init__(self):
        self._heap: List[Tuple[float, int, SparTreeNode]] = []
        self._counter = itertools.count()

    def push(self, node: SparTreeNode, attention: float) -> None:
        """Push a node with its attention weight (lower = earlier)."""
        heapq.heappush(self._heap, (attention, next(self._counter), node))

    def pop(self) -> SparTreeNode:
        """Pop and return the node with the lowest attention weight."""
        return heapq.heappop(self._heap)[2]

    def is_empty(self) -> bool:
        """Return True when the queue holds no nodes."""
        return not self._heap

    def __len__(self) -> int:
        return len(self._heap)
